/* Simulated-annealing census for the two-generator Titz--Witzel sofic gate
 * (TW2G2) of research/titz-witzel-sofic-gate-two-generators-four-approximate-relators.md.
 *
 * Variables: e an involution of {0..n-1} (exact, maintained by every move), u a permutation.
 * Relators (letters 1=e, 2=u, -2=u^-1), generated by words.py from the recorded word check.
 * Defect D = sum over the four approximate relators r of d_H(r,1) = (#points moved)/n.
 * Mark   M = d_H(u^8,1).
 * Objective  J = D + LAMBDA * max(0, M0 - M).
 * Output: best D found with M >= M0, per (n, seed).
 *
 * Words are applied as a right action x -> x.l1.l2...; this is a homomorphism from the free
 * group with generators replaced by their inverses, which is again a model of the gate
 * (e is an involution, and replacing u by u^-1 is a bijection on models), so defects and marks
 * are exactly those of a genuine assignment.
 *
 * Usage: gate_anneal n seed steps M0 lambda [mask]
 *   mask (default 15) selects which of the four approximate relators count in D; the
 *   printed per-relator counts are always for all four.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include "relators.h"

static int n;
static int *E, *U, *Ui;
static int MASK = 15;   /* which approximate relators count in D (control runs drop one) */

static unsigned long long rs;
static inline unsigned long long rnd(void) {
    rs ^= rs << 13; rs ^= rs >> 7; rs ^= rs << 17; return rs;
}

static inline int apply_letter(int x, int l) {
    if (l == 1) return E[x];
    if (l == 2) return U[x];
    return Ui[x];
}

static int moved(const int *w, int len) {
    int cnt = 0;
    for (int x = 0; x < n; x++) {
        int y = x;
        for (int k = 0; k < len; k++) y = apply_letter(y, w[k]);
        if (y != x) cnt++;
    }
    return cnt;
}

static void eval(double *D, double *M, int *per) {
    int tot = 0;
    for (int r = 0; r < NREL; r++) {
        per[r] = moved(REL[r], RLEN[r]);
        if (MASK & (1 << r)) tot += per[r];
    }
    static const int u8[8] = {2, 2, 2, 2, 2, 2, 2, 2};
    *D = (double)tot / n;
    *M = (double)moved(u8, 8) / n;
}

int main(int argc, char **argv) {
    if (argc < 6) { fprintf(stderr, "usage\n"); return 1; }
    n = atoi(argv[1]);
    rs = 0x9E3779B97F4A7C15ULL ^ (unsigned long long)atoll(argv[2]) * 0x2545F4914F6CDD1DULL;
    long steps = atol(argv[3]);
    double M0 = atof(argv[4]), LAMBDA = atof(argv[5]);
    if (argc > 6) MASK = atoi(argv[6]);
    E = malloc(n * sizeof(int)); U = malloc(n * sizeof(int)); Ui = malloc(n * sizeof(int));
    int *Eb = malloc(n * sizeof(int)), *Ub = malloc(n * sizeof(int));
    int *Ebest = malloc(n * sizeof(int)), *Ubest = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) U[i] = i;
    for (int i = n - 1; i > 0; i--) { int j = rnd() % (i + 1); int t = U[i]; U[i] = U[j]; U[j] = t; }
    for (int i = 0; i < n; i++) E[i] = i;
    { int *perm = malloc(n * sizeof(int));
      for (int i = 0; i < n; i++) perm[i] = i;
      for (int i = n - 1; i > 0; i--) { int j = rnd() % (i + 1); int t = perm[i]; perm[i] = perm[j]; perm[j] = t; }
      for (int i = 0; i + 1 < n; i += 2) { E[perm[i]] = perm[i + 1]; E[perm[i + 1]] = perm[i]; }
      free(perm); }
    for (int i = 0; i < n; i++) Ui[U[i]] = i;
    double D, M; int per[NREL];
    eval(&D, &M, per);
    double J = D + LAMBDA * fmax(0.0, M0 - M);
    double bestD = 1e9, bestM = 0; int bestper[NREL] = {0};
    double T0 = 0.5, T1 = 0.0005;
    for (long s = 0; s < steps; s++) {
        double T = T0 * pow(T1 / T0, (double)s / steps);
        memcpy(Eb, E, n * sizeof(int)); memcpy(Ub, U, n * sizeof(int));
        if (rnd() & 1) {           /* swap two images of u */
            int a = rnd() % n, b = rnd() % n;
            int t = U[a]; U[a] = U[b]; U[b] = t;
        } else {                    /* re-pair e: x,y become a pair (or both fixed) */
            int x = rnd() % n, y = rnd() % n;
            if (x == y) { int p = E[x]; E[x] = x; E[p] = p; }
            else {
                int px = E[x], py = E[y];
                if (px == y) { E[x] = x; E[y] = y; }
                else {
                    E[px] = px; E[py] = py;
                    E[x] = y; E[y] = x;
                    if (px != x && py != y) { E[px] = py; E[py] = px; }
                }
            }
        }
        for (int i = 0; i < n; i++) Ui[U[i]] = i;
        double D2, M2; int per2[NREL];
        eval(&D2, &M2, per2);
        double J2 = D2 + LAMBDA * fmax(0.0, M0 - M2);
        if (J2 <= J || exp((J - J2) / T) > (double)(rnd() % 1000000) / 1e6) {
            J = J2; D = D2; M = M2; memcpy(per, per2, sizeof per);
            if (M >= M0 && D < bestD) {
                bestD = D; bestM = M; memcpy(bestper, per, sizeof per);
                memcpy(Ebest, E, n * sizeof(int)); memcpy(Ubest, U, n * sizeof(int));
            }
        } else {
            memcpy(E, Eb, n * sizeof(int)); memcpy(U, Ub, n * sizeof(int));
            for (int i = 0; i < n; i++) Ui[U[i]] = i;
        }
    }
    /* verify e is an involution in the best model */
    int ok = 1;
    for (int i = 0; i < n; i++) if (Ebest[Ebest[i]] != i) ok = 0;
    printf("n=%d seed=%s steps=%ld M0=%.3f bestD=%.5f bestM=%.4f per=%d,%d,%d,%d invol=%d\n",
           n, argv[2], steps, M0, bestD, bestM, bestper[0], bestper[1], bestper[2], bestper[3], ok);
    if (argc > 7 && atoi(argv[7])) {   /* dump the best model */
        printf("e =");
        for (int i = 0; i < n; i++) printf(" %d", Ebest[i]);
        printf("\nu =");
        for (int i = 0; i < n; i++) printf(" %d", Ubest[i]);
        printf("\n");
    }
    return 0;
}
